SELECT 'core-2026-09-v4','modal-obligation','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"modal-obligation","title":"Obligation, advice and prohibition","level":"B1","order":39,"summary":"Separate what is required, forbidden, unnecessary or advisable.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Must and have to","Forbidden is different from optional","Advice and expectations","Form questions and negatives correctly"],"rules":[{"title":"Must and have to","explanation":"Must and have to can both express obligation. Have to is especially useful for external requirements and for past or future forms. Must often expresses a strong rule or the speaker’s judgement. The distinction is a tendency, not a rigid division.","pattern":"You **must wear** a helmet. / We **had to wait**.","commonMistakes":["Must has no ordinary past-tense form for obligation. Use had to, not musted."],"examples":["The rule forbids the task. “You **must not** prepare the visitor guide.”","The rule forbids the task. “You **must not** restore the old portrait.”"],"skill":"form"},{"title":"Forbidden is different from optional","explanation":"**Must not** expresses prohibition. **Do not have to** means there is no obligation; the action is still allowed. This contrast is crucial when interpreting instructions. Need not can also mean that an action is unnecessary.","pattern":"You **must not enter**. / You **do not have to enter**.","commonMistakes":["Must not enter does not mean entering is optional. It means entering is forbidden."],"examples":["The task is optional and allowed. “You **do not have to** prepare the visitor guide.”","The task is optional and allowed. “You **do not have to** restore the old portrait.”"],"skill":"meaning"},{"title":"Advice and expectations","explanation":"Should and ought to commonly give advice or say what is expected. Should takes a bare infinitive; ought takes to. Had better gives stronger situation-specific advice and is followed by a base verb.","pattern":"You **should rest**. / You **ought to rest**. / You **had better rest**.","commonMistakes":["Had better is normally about the present or future despite had; it is not simply past advice."],"examples":["Give advice: “She should **prepare** the visitor guide before Friday.”","Give advice: “She should **restore** the old portrait before Friday.”"],"skill":"contrast"},{"title":"Form questions and negatives correctly","explanation":"Have to behaves like a lexical verb for do-support: Does she have to? She does not have to. Must and should form their own questions and negatives. Choose the auxiliary pattern that belongs to the expression.","pattern":"**Does she have to** leave? / **Should she** leave?","commonMistakes":["Does she has to? marks agreement twice; after does, use have."],"examples":["Ask about the requirement: “Does she **have to prepare** the visitor guide today?”","Ask about the requirement: “Does she **have to restore** the old portrait today?”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-obligation"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Separate what is required, forbidden, unnecessary or advisable.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Must and have to","explanation":"Must and have to can both express obligation. Have to is especially useful for external requirements and for past or future forms. Must often expresses a strong rule or the speaker’s judgement. The distinction is a tendency, not a rigid division.","pattern":"You **must wear** a helmet. / We **had to wait**.","commonMistakes":["Must has no ordinary past-tense form for obligation. Use had to, not musted."],"examples":["The rule forbids the task. “You **must not** prepare the visitor guide.”","The rule forbids the task. “You **must not** restore the old portrait.”"],"skill":"form","id":"modal-obligation-foundation-1","domain":"verbs","referenceIds":["bc-obligation"],"readingVersion":"core-2026-09-v3"},{"title":"Forbidden is different from optional","explanation":"**Must not** expresses prohibition. **Do not have to** means there is no obligation; the action is still allowed. This contrast is crucial when interpreting instructions. Need not can also mean that an action is unnecessary.","pattern":"You **must not enter**. / You **do not have to enter**.","commonMistakes":["Must not enter does not mean entering is optional. It means entering is forbidden."],"examples":["The task is optional and allowed. “You **do not have to** prepare the visitor guide.”","The task is optional and allowed. “You **do not have to** restore the old portrait.”"],"skill":"meaning","id":"modal-obligation-foundation-2","domain":"verbs","referenceIds":["bc-obligation"],"readingVersion":"core-2026-09-v3"},{"title":"Advice and expectations","explanation":"Should and ought to commonly give advice or say what is expected. Should takes a bare infinitive; ought takes to. Had better gives stronger situation-specific advice and is followed by a base verb.","pattern":"You **should rest**. / You **ought to rest**. / You **had better rest**.","commonMistakes":["Had better is normally about the present or future despite had; it is not simply past advice."],"examples":["Give advice: “She should **prepare** the visitor guide before Friday.”","Give advice: “She should **restore** the old portrait before Friday.”"],"skill":"contrast","id":"modal-obligation-foundation-3","domain":"verbs","referenceIds":["bc-obligation"],"readingVersion":"core-2026-09-v3"},{"title":"Form questions and negatives correctly","explanation":"Have to behaves like a lexical verb for do-support: Does she have to? She does not have to. Must and should form their own questions and negatives. Choose the auxiliary pattern that belongs to the expression.","pattern":"**Does she have to** leave? / **Should she** leave?","commonMistakes":["Does she has to? marks agreement twice; after does, use have."],"examples":["Ask about the requirement: “Does she **have to prepare** the visitor guide today?”","Ask about the requirement: “Does she **have to restore** the old portrait today?”"],"skill":"application","id":"modal-obligation-foundation-4","domain":"verbs","referenceIds":["bc-obligation"],"readingVersion":"core-2026-09-v3"},{"domain":"verbs","id":"modal-meanings-and-semi-modals","title":"Modal meanings and semi-modal expressions","explanation":"Modals express judgements, possibilities, requirements, willingness and interpersonal meanings. The same form can have several uses. Expressions such as have to, be able to, be allowed to and be supposed to supply forms or meanings that central modals lack. Their question and negative grammar differs from that of can or must.","pattern":"**must leave** / **had to leave**","examples":["You **are supposed to sign** here.","Will you help? can ask about **willingness**, not only future time."],"commonMistakes":["Central modals do not normally combine directly: will can is not standard. Use an appropriate expression such as will be able to."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"verbs","id":"ought-need-dare-had-better","title":"Ought to, need, dare, had better and would rather","explanation":"Ought usually takes to; had better takes the bare infinitive and often carries a warning about consequences. Need and dare can behave as ordinary verbs or, in some uses and varieties, as modal-like auxiliaries. Would rather expresses preference. Learn their construction patterns as well as their broad meanings.","pattern":"You **had better leave**. / You **ought to leave**.","examples":["You **need not wait**. / You **do not need to wait**.","I **would rather stay** than leave."],"commonMistakes":["Had better concerns a present or future recommendation despite had. Its ordinary negative is had better not; it is not a statement about the past."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"negation","id":"negation-auxiliaries","title":"Building negatives with and without auxiliaries","explanation":"In an ordinary finite negative, not follows the first auxiliary. If a lexical verb has no auxiliary, present and past simple normally add do. Be makes its own negative, and imperative be uses do not. Non-finite constructions can place not before the infinitive or participle. Identify the construction before placing the negative.","pattern":"does **not** know · has **not** been told","examples":["**Do not be** late.","She asked us **not to wait**."],"commonMistakes":["A negative prefix changes a word, while not can negate a phrase or clause. Unhappy and not happy can differ in implication."],"referenceIds":["cambridge-negation","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"negation","id":"modal-negative-scope","title":"Mustn’t, don’t have to and can’t: what is negated?","explanation":"A modal and a negative can interact in different ways. Must not normally prohibits an action; not have to denies necessity. Cannot denies ability, permission or possibility according to context. May not can deny permission or describe a negative possibility. Identify whether the negative affects the event or the modal judgement.","pattern":"**must not go** / **do not have to go**","examples":["You **mustn’t enter**: entry is prohibited.","She **may not come**: perhaps she will stay away."],"commonMistakes":["May not come can also mean that permission is refused in a suitable context. An explanation should state the intended reading rather than pretend the words have only one meaning."],"referenceIds":["cambridge-negation","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["You **must wear** a helmet. / We **had to wait**.","You **must not enter**. / You **do not have to enter**.","You **should rest**. / You **ought to rest**. / You **had better rest**.","**Does she have to** leave? / **Should she** leave?"],"readingVersion":"core-2026-09-v4"},"stage":"4 · Connecting meanings","prerequisites":["dependent-prepositions"],"readingReferenceIds":["bc-obligation","cambridge-comprehensive-scope","cambridge-negation"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='modal-obligation'
